// Verifies the HMAC signature Convex puts on every loan event.
// signature = hex(HMAC_SHA256(CONVEX_TO_N8N_SECRET, timestamp + "." + rawBody))
// Fails closed: anything unexpected is treated as invalid.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;

const secret = $env.CONVEX_TO_N8N_SECRET;
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'] || '';

let verdict = 'invalid';
let reason = '';
let payload = null;

try {
  if (!secret) throw new Error('CONVEX_TO_N8N_SECRET is not set');
  if (!item.binary || !item.binary.data) throw new Error('raw body missing');
  const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');

  const now = Math.floor(Date.now() / 1000);
  if (!/^\d+$/.test(timestamp || '')) throw new Error('bad timestamp');
  if (Math.abs(now - Number(timestamp)) > MAX_SKEW_SECONDS) throw new Error('stale timestamp');

  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(signature);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('bad signature');

  payload = JSON.parse(raw);
  // Dedupe: Convex may retry if our response got lost after the email went out.
  const seen = $getWorkflowStaticData('global').seen || [];
  verdict = seen.includes(payload.idempotencyKey) ? 'duplicate' : 'ok';
} catch (err) {
  reason = err.message;
}

// Never echo the payload back for invalid requests.
return [{ json: { verdict, reason, payload: verdict === 'invalid' ? null : payload } }];

// Builds the email for one loan event. Uses only the minimal fields Convex sent.
const p = $json.payload;
const appUrl = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const range = p.startDate === p.endDate ? p.startDate : p.startDate + ' → ' + p.endDate;
const first = (p.recipient.name || '').split(/\s+/)[0] || 'there';

const templates = {
  requested: {
    subject: 'New borrow request for your ' + p.toolName,
    text: p.counterpartFirstName + ' would like to borrow your ' + p.toolName + ' (' + range + ').\n\nReview it: ' + appUrl + '/my/incoming',
  },
  cancelled: {
    subject: 'Request cancelled: ' + p.toolName,
    text: p.counterpartFirstName + ' cancelled their request for your ' + p.toolName + ' (' + range + ').',
  },
  approved: {
    subject: 'Approved: you can borrow the ' + p.toolName,
    text: p.counterpartFirstName + ' approved your request for the ' + p.toolName + ' (' + range + ').\n\nDetails: ' + appUrl + '/my/requests',
  },
  rejected: {
    subject: 'Request declined: ' + p.toolName,
    text: 'Your request for the ' + p.toolName + ' (' + range + ') was declined. Other tools: ' + appUrl + '/tools',
  },
  returned: {
    subject: 'Return confirmed: ' + p.toolName,
    text: p.counterpartFirstName + ' confirmed the ' + p.toolName + ' is back. Thanks for borrowing responsibly!',
  },
};
const t = templates[p.status];
if (!t) throw new Error('Unknown loan status: ' + p.status);

// "Log" channel: one structured line per notification in the execution log (no email body).
console.log(JSON.stringify({ event: 'loan_notification', key: p.idempotencyKey, status: p.status, to: p.recipientRole }));

return [{ json: {
  to: p.recipient.email,
  subject: '[LendLoop] ' + t.subject,
  text: 'Hi ' + first + ',\n\n' + t.text + '\n\n— LendLoop',
  idempotencyKey: p.idempotencyKey,
} }];

// Remember processed events so a Convex retry doesn't send a second email.
const data = $getWorkflowStaticData('global');
const key = $('Compose email').first().json.idempotencyKey;
data.seen = [...(data.seen || []).filter((k) => k !== key), key].slice(-500);
return [{ json: { ok: true, idempotencyKey: key } }];
